## contract-smoke.R -- curated "hero" conformance cases (fast; runs every build).
## generated by the validation scaffold for flexyBayes. The case-object contract (engine/conformance.R):
##   list(fn, source = "curated", expect = "ok"|"error", label,
##        call = function() ..., check = function(v) <oracle> | NULL)
## Each NULL-input negative below is runnable on emit: a well-validated function
## REJECTS it (expect = "error"); if it does not, the conformance engine records
## the unguarded input as a finding -- itself useful signal. Add the positive
## (valid-input + oracle) case per function to make this a real correctness gate.
## Run from report/.
`%||%` <- function(a, b) if (is.null(a)) b else a
## Ensure flexyBayes is loaded whether installed or only present as source under study
## (build.R's `smoke` mode already load_all()s it via _setup.R; this is the
## standalone-safe fallback).
if (!isNamespaceLoaded("flexyBayes")) {
  if (requireNamespace("devtools", quietly = TRUE) && dir.exists(file.path("..", "flexyBayes"))) {
    suppressMessages(devtools::load_all(file.path("..", "flexyBayes"), quiet = TRUE))
  } else {
    suppressMessages(library(flexyBayes))
  }
}
RESDIR <- "bench/results"
dir.create(RESDIR, showWarnings = FALSE, recursive = TRUE)

CURATED <- list(
  ## --- fb ---
  list(fn = "fb", source = "curated", expect = "error",
       label = "fb: NULL input rejected",
       call = function() fb(NULL), check = NULL),
  ## --- fb_inla ---
  list(fn = "fb_inla", source = "curated", expect = "error",
       label = "fb_inla: NULL input rejected",
       call = function() fb_inla(NULL), check = NULL),
  ## --- fb_greta ---
  list(fn = "fb_greta", source = "curated", expect = "error",
       label = "fb_greta: NULL input rejected",
       call = function() fb_greta(NULL), check = NULL)
)
## TODO(author): add a POSITIVE case (valid input + a correctness oracle) per
## function to make this a real correctness gate -- paste into CURATED and complete:
##   list(fn = "fb", source = "curated", expect = "ok",
##        label = "fb: valid input is correct",
##        call = function() fb(<valid args>),
##        check = function(v) <TRUE iff v matches an independent oracle>),
##   list(fn = "fb_inla", source = "curated", expect = "ok",
##        label = "fb_inla: valid input is correct",
##        call = function() fb_inla(<valid args>),
##        check = function(v) <TRUE iff v matches an independent oracle>),
##   list(fn = "fb_greta", source = "curated", expect = "ok",
##        label = "fb_greta: valid input is correct",
##        call = function() fb_greta(<valid args>),
##        check = function(v) <TRUE iff v matches an independent oracle>),

verdicts <- pv_grid(
  CURATED, fn = function(cs) cs$call(),
  expect = function(cs) cs$expect, label = function(cs, i) cs$label,
  check = function(v, cs) if (is.null(cs$check)) TRUE else isTRUE(cs$check(v)),
  ## Drop to cores = 1L if the package uses a backend that is unsafe to fork
  ## (e.g. torch / Metal): pv_grid parallelises with forked workers.
  cores = 4L, base_seed = 20260625L)
verdicts$fn <- vapply(CURATED, function(cs) cs$fn, character(1))[verdicts$idx]
verdicts$source <- vapply(CURATED, function(cs) cs$source %||% "curated",
                          character(1))[verdicts$idx]

## TODO(author): package-specific metamorphic invariants (the harness is generic).
META <- pv_metamorphic_suite(list(
  ## "identity map" = function() pv_metamorphic(<f(x)>, <x>, what = "f is identity")
))

conf <- pv_assemble_conformance(verdicts, META,
                                surface = getNamespaceExports("flexyBayes"),
                                master_seed = 20260625L,
                                provenance = pv_provenance("../flexyBayes"))
saveRDS(conf, file.path(RESDIR, "contract-conformance.rds"))
cat(sprintf("contract-smoke: %d cells, %d findings, coverage %.2f\n",
            conf$n_cells, conf$n_findings, conf$api_surface_covered %||% NA_real_))
